SourceCode.Declaration:
using System;
using System.Text;

public class METFulfilmentProfileEntity extends common
{
}

Method.Source:
/// <summary>
/// Builds raw pipe-delimited condition string using AOT Names.
/// </summary>
private Notes getRawConditions(METFulfilmentProfileId _profileId)
{
    Notes queryString = '';
    container packedQuery = METFulfilmentProfile::find(_profileId).ConditionQueryPacked;

    if (conLen(packedQuery) == 0)
    {
        return queryString;
    }

    Query condition = new Query(packedQuery);
    Set processedTables = new Set(Types::Integer);

    int nFilter = condition.queryFilterCount();
    for (int iFilter = 1; iFilter <= nFilter; iFilter++)
    {
        QueryFilter qf = condition.queryFilter(iFilter);
        if (qf && qf.value() && qf.status() != RangeStatus::Hidden)
        {
            QueryBuildDataSource qbds = qf.dataSource();
            if (qbds)
            {
                TableName tableName = tableId2Name(qbds.table());
                FieldName fieldName = qf.field();
                if (tableName && fieldName)
                {
                    queryString += strFmt("%1; %2; %3|", tableName, fieldName, qf.value());
                    processedTables.add(qbds.table());
                }
            }
        }
    }

    // Export QueryBuildRanges and Standalone Joined Data Sources
    for (int dsI = 1; dsI <= condition.dataSourceCount(); dsI++)
    {
        QueryBuildDataSource qbds = condition.dataSourceNo(dsI);
        if (qbds)
        {
            boolean hasRange = false;
            int nRange = qbds.rangeCount();

            for (int iRange = 1; iRange <= nRange; iRange++)
            {
                QueryBuildRange qbr = qbds.range(iRange);
                if (qbr && qbr.value() && qbr.status() != RangeStatus::Hidden)
                {
                    TableName tableName = tableId2Name(qbr.table());
                    FieldName fieldName = fieldId2Name(qbr.table(), qbr.field());
                    if (tableName && fieldName)
                    {
                        queryString += strFmt("%1; %2; %3|", tableName, fieldName, qbr.value());
                        hasRange = true;
                        processedTables.add(qbds.table());
                    }
                }
            }

            if (!hasRange && !processedTables.in(qbds.table()) && dsI > 1)
            {
                TableName tableName = tableId2Name(qbds.table());
                if (tableName)
                {
                    queryString += strFmt("%1|", tableName);
                    processedTables.add(qbds.table());
                }
            }
        }
    }

    return queryString;
}

/// <summary>
/// Encodes plain-text AOT conditions to Base64 for clean CSV export.
/// </summary>
public Notes getConditions(METFulfilmentProfileId _profileId)
{
    Notes rawConditions = this.getRawConditions(_profileId);

    if (!rawConditions)
    {
        return '';
    }

    System.Byte[] bytes = System.Text.Encoding::UTF8.GetBytes(rawConditions);
    str encoded = System.Convert::ToBase64String(bytes);

    // Strip line breaks to guarantee single CSV line execution
    encoded = strReplace(encoded, num2char(13), '');
    encoded = strReplace(encoded, num2char(10), '');

    return encoded;
}

/// <summary>
/// Builds condition query supporting Base64-encoded strings and legacy plain-text.
/// </summary>
public static Query buildConditionQuery(str _conditions, METFulfilmentProfileId _profileId)
{
    Query query = METFulfilmentProfile::defaultQuery();
    str decodedConditions = _conditions;

    if (!_conditions)
    {
        return query;
    }

    // attempt Base64 Decoding with fallback to plain text
    try
    {
        System.Byte[] bytes = System.Convert::FromBase64String(_conditions);
        decodedConditions = System.Text.Encoding::UTF8.GetString(bytes);
    }
    catch
    {
        decodedConditions = _conditions;
    }

    //  Pre-set One2One fetch mode across all data sources
    for (int i = 1; i <= query.dataSourceCount(); i++)
    {
        query.dataSourceNo(i).fetchMode(QueryFetchMode::One2One);
    }

    List conditionsList = strSplit(decodedConditions, '|');
    ListEnumerator conditionsEnum = conditionsList.getEnumerator();

    while (conditionsEnum.moveNext())
    {
        str condition = strLTrim(strRTrim(conditionsEnum.current()));
        if (!condition)
        {
            continue;
        }

        List conditionParts = strSplit(condition, ';');
        ListEnumerator partsEnum = conditionParts.getEnumerator();

        str tablePart = '', fieldPart = '', value = '';
        int partCounter = 1;

        while (partsEnum.moveNext())
        {
            str val = strLTrim(strRTrim(partsEnum.current()));
            if (partCounter == 1)
            {
                tablePart = val;
            }
            else if (partCounter == 2)
            {
                fieldPart = val;
            }
            else if (partCounter == 3)
            {
                value = val;
            }
            partCounter++;
        }

        if (!tablePart)
        {
            continue;
        }

        TableId tableId = tableName2Id(tablePart);
        if (!tableId)
        {
            tableId = str2Int(tablePart);
        }
        if (!tableId)
        {
            continue;
        }

        QueryBuildDataSource qbds = query.dataSourceTable(tableId);

        if (!qbds)
        {
            QueryBuildDataSource rootQbds = query.dataSourceNo(1);
            if (rootQbds)
            {
                qbds = rootQbds.addDataSource(tableId);
                qbds.joinMode(JoinMode::OuterJoin);
                qbds.fetchMode(QueryFetchMode::One2One);
                qbds.relations(true);
            }
        }

        if (!qbds || !fieldPart)
        {
            continue;
        }

        FieldId fieldId = fieldName2Id(tableId, fieldPart);
        if (!fieldId)
        {
            fieldId = str2Int(fieldPart);
        }
        if (!fieldId)
        {
            continue;
        }

        FieldName conditionFieldName = fieldId2Name(tableId, fieldId);
        if (!conditionFieldName)
        {
            continue;
        }

        if (qbds.joinMode() == JoinMode::OuterJoin)
        {
            QueryFilter queryFilter = SysQuery::findOrCreateQueryFilter(query, qbds, conditionFieldName);
            if (queryFilter)
            {
                queryFilter.value(value);
            }
        }
        else
        {
            QueryBuildRange qbr = qbds.findRange(fieldId);
            if (!qbr)
            {
                qbr = qbds.addRange(fieldId);
            }
            qbr.value(value);
        }
    }

    return query;
}

/// <summary>
/// Populates conditions on export
/// </summary>
public void postLoad()
{
    super();

    if (this.ProfileId)
    {
        this.Conditions = this.getConditions(this.ProfileId);
    }
}

/// <summary>
/// Maps conditions on row-level import
/// </summary>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    METFulfilmentProfile fulfilmentProfile;

    super(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() != dataEntityDataSourceStr(METFulfilmentProfileEntity, METFulfilmentProfile)
        || !this.Conditions)
    {
        return;
    }

    fulfilmentProfile = _dataSourceCtx.getBuffer() as METFulfilmentProfile;

    if (fulfilmentProfile)
    {
        fulfilmentProfile.ConditionQueryPacked =
            METFulfilmentProfileEntity::buildConditionQuery(this.Conditions, this.ProfileId).pack();
    }
}

/// <summary>
/// Post-target set-based processing across companies
/// </summary>
public static void postTargetProcess(DMFDefinitionGroupExecution _dmfDefinitionGroupExecution)
{
    METFulfilmentProfileStaging staging;
    METFulfilmentProfile        targetProfile;

    ttsbegin;

    while select staging
        where staging.DefinitionGroup == _dmfDefinitionGroupExecution.DefinitionGroup
           && staging.ExecutionId     == _dmfDefinitionGroupExecution.ExecutionId
    {
        if (!staging.ProfileId)
        {
            continue;
        }

        select firstonly crosscompany targetProfile
            where targetProfile.ProfileId == staging.ProfileId;

        if (targetProfile.RecId)
        {
            RecId targetRecId = targetProfile.RecId;

            changecompany(targetProfile.DataAreaId)
            {
                select firstonly forupdate targetProfile
                    where targetProfile.RecId == targetRecId;

                if (staging.Conditions)
                {
                    targetProfile.ConditionQueryPacked =
                        METFulfilmentProfileEntity::buildConditionQuery(staging.Conditions, staging.ProfileId).pack();
                }

                if (staging.Description)
                {
                    targetProfile.Description = staging.Description;
                }

                if (staging.InventLocationId)
                {
                    targetProfile.InventLocationId = staging.InventLocationId;
                }

                targetProfile.ApplicableProcess = staging.ApplicableProcess
                    ? staging.ApplicableProcess
                    : METFulfilmentProfileApplicableProcess::CSDSalesOrderExtract;

                targetProfile.update();
            }
        }
        else
        {
            changecompany(staging.DataAreaId)
            {
                targetProfile.clear();
                targetProfile.ProfileId         = staging.ProfileId;
                targetProfile.Description       = staging.Description;
                targetProfile.InventLocationId  = staging.InventLocationId;
                targetProfile.ApplicableProcess = staging.ApplicableProcess
                    ? staging.ApplicableProcess
                    : METFulfilmentProfileApplicableProcess::CSDSalesOrderExtract;

                if (staging.Conditions)
                {
                    targetProfile.ConditionQueryPacked =
                        METFulfilmentProfileEntity::buildConditionQuery(staging.Conditions, staging.ProfileId).pack();
                }
                else
                {
                    targetProfile.ConditionQueryPacked = METFulfilmentProfile::defaultQuery().pack();
                }

                targetProfile.insert();
            }
        }
    }

    ttscommit;
}
